                "target/apalache/toolchains/v0.52.2/bin/apalache-mc --version",
                "bash scripts/formal/sumeragi_apalache.sh frontier-bug-stale-owner",
                'echo "[formal] Sumeragi expected-failure checks behaved as expected"',
