                "vars == <<checked>>",
                "Init == checked = 0",
                "ByzantineDirectCommitNext == checked' = 1",
                "TypeInvariant == TRUE",
                "TlcByzantineDirectCommitCorridor == checked = 0",
                "ByzantineDirectTopCorrectnessEnvelope == checked = 1",
                "ByzantineDirectTopCoversOrderedTopCorridors == checked \\in 0..1",
                "====",
