def make_byzantine_mutation_cfgs(
    tmp_path: Path,
    stem_prefix: str,
    suffixes: tuple[str, ...],
) -> list[Path]:
    paths: list[Path] = []
    for suffix in suffixes:
        cfg = tmp_path / f"{stem_prefix}{suffix}.cfg"
        cfg.write_text(
            "INIT Init\nNEXT Next\nINVARIANT TypeInvariant\n",
            encoding="utf-8",
        )
        paths.append(cfg)
    return paths


