def write_cfg_with_constant_values(
    path: Path,
    constant_values: tuple[tuple[str, str], ...],
) -> None:
    path.write_text(
        "\n".join(
            [
                "INIT Init",
                "NEXT Next",
                "CONSTANTS",
                *(f"  {constant} = {value}" for constant, value in constant_values),
                "INVARIANT TypeInvariant",
            ]
        ),
        encoding="utf-8",
    )


